import socket, re, time, ast  
from crypto.util.number import bytes_to_long  

# minimal re-implementation of the server's prng and shuffle logic:
class prng:
    def __init__(self, seed):
        self.state = [seed]
        self.index = 64
        for i in range(63):
            self.state.append((3*(self.state[i] ^ (self.state[i-1]>>4)) + i + 1) % 64)
    def _refresh(self):
        for i in range(64):
            y = (self.state[i]&0x20)+(self.state[(i+1)%64]&0x1f)
            val = y>>1
            val ^= self.state[(i+42)%64]
            if (y&1):
                val ^= 37
            self.state[i] = val
        self.index = 0
    def getnum(self):
        if self.index>=64:
            self._refresh()
        s = self.state[self.index]
        self.index+=1
        return (s*15 + 17)%(2**6)

# build the initial deck in the same order the server does:
suits = ["spades","hearts","diamonds","clubs"]
deck0 = []
for suit in suits:
    for rank in range(16):
        deck0.append((suit,rank))  # (suit, rank)

def shuffle_deck(d, rng):
    newd = []
    for i in range(64):
        x = rng.getnum()
        if d[x] not in newd:
            newd.append(d[x])
        elif d[i] not in newd:
            newd.append(d[i])
        else:
            for c in d:
                if c not in newd:
                    newd.append(c)
                    break
    return newd

def encrypt_card(card, n):
    # card is (suit, rank), turned into b"value of suit"
    cv = [
        "zero","one","two","three","four","five","six","seven",
        "eight","nine","ten","jack","queen","king","ace","joker"
    ]
    val = cv[card[1]]+" of "+card[0]
    return bytes_to_long(val.encode()) % n

# compare entire deck vs the server's 64-cipher array to see if seed matches
def check_seed_candidates(enc_deck, deck_in, n):
    # try all seeds 0..63
    for seed in range(64):
        test_rng = prng(seed)
        d = deck_in[:]
        d = shuffle_deck(d, test_rng)
        test_enc = []
        for c in d:
            test_enc.append(encrypt_card(c, n))
        if test_enc==enc_deck:
            return seed
    return none

# reorder so that computer gets worst 5, user gets best 5 => guaranteed user win
# we'll pick computer 5 as ranks [0,1,2,3,4], user 5 as [15,15,15,15,14].
def reorder_for_win(d):
    # build a dictionary from (suit,rank) -> index
    # we'll pick for the user: four jokers + one ace
    usercardsneeded = [(15,"spades"), (15,"hearts"), (15,"diamonds"), (15,"clubs"), (14,"spades")]
    # we'll pick for the computer: [0,1,2,3,4] in any suits
    compcardsneeded = [(0,"spades"), (1,"spades"), (2,"spades"), (3,"spades"), (4,"spades")]

    # we'll find them in d, remove them, then gather remainder
    neworder = []
    used = set()
    for need in compcardsneeded:
        for i,c in enumerate(d):
            if i not in used and (c[1],c[0])==(need[1],need[0])==false and c==(need[0],need[1])==false:
                # we might have the ordering as (suit,rank), so check carefully:
                if (c[1]==need[1] and c[0]==need[0]):  # rank->need[1], suit->need[0]
                    neworder.append(c)
                    used.add(i)
                    break
    # if some not found, just fill
    while len(neworder)<5:
        for i,c in enumerate(d):
            if i not in used:
                neworder.append(c)
                used.add(i)
                break

    for need in usercardsneeded:
        for i,c in enumerate(d):
            if i not in used and (c[1]==need[0] and c[0]==need[1])==false and (c[0]==need[1] and c[1]==need[0]):
                if (c[1]==need[1] and c[0]==need[0]):
                    neworder.append(c)
                    used.add(i)
                    break
    while len(neworder)<10:
        for i,c in enumerate(d):
            if i not in used:
                neworder.append(c)
                used.add(i)
                break

    # fill remainder
    for i,c in enumerate(d):
        if i not in used:
            neworder.append(c)
            used.add(i)
    return neworder

